export class TimeoutError extends Error {
    readonly label: string;

    constructor(label: string, ms: number) {
        super(`${label} timed out after ${ms}ms`);
        this.name = "TimeoutError";
        this.label = label;
    }
}

// Gives `work` at most `ms` milliseconds. The signal passed to `work` is aborted when the time is up,
// so it can cancel its request. The timer is always cleared.
export function withTimeout<T>(label: string, ms: number, work: (signal: AbortSignal) => Promise<T>): Promise<T> {
    const controller = new AbortController();
    return new Promise<T>((resolve, reject) => {
        const timer = setTimeout(() => {
            const err = new TimeoutError(label, ms);
            controller.abort(err); // ask the work to stop, if it can
            reject(err); // and stop waiting for it either way
        }, ms);
        work(controller.signal).then(
            (value) => {
                clearTimeout(timer);
                resolve(value);
            },
            (err) => {
                clearTimeout(timer);
                reject(err);
            },
        );
    });
}
